<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free WebP to JPG Converter Online','description'=>'Convert WebP images to JPG directly in your browser.','url'=>'https://smarttoolz.in/tools/webp-to-jpg/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">WEBP TO JPG</span><h1>WebP to JPG Converter</h1><p>Choose a WebP image, convert it locally and download the JPG.</p></section><section class="tool-workspace"><div class="tool-panel"><label>WebP image<input id="f" type="file" accept="image/webp"></label><label>Quality<input id="q" type="range" min="10" max="100" value="90"></label><button id="go" class="tool-btn">Convert to JPG</button><p id="out"></p><a id="dl" class="tool-btn" hidden download="converted.jpg">Download JPG</a></div></section></main><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=()=>{let f=$('f').files[0];if(!f){$('out').textContent='Choose a WebP file.';return}let im=new Image(),u=URL.createObjectURL(f);im.onload=()=>{let c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);c.toBlob(b=>{let d=URL.createObjectURL(b);$('dl').href=d;$('dl').hidden=false;$('out').textContent='Conversion complete.';URL.revokeObjectURL(u)},'image/jpeg',+$('q').value/100)};im.src=u}})();</script><?php smarttoolz_tool_page_end(); ?>